package com.gymmind.membership.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.membership.domain.model.*; import com.gymmind.membership.domain.repository.*; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map; @Service public class DefaultMemberMembershipService implements MemberMembershipService{private final MemberMembershipRepository memberships;private final MembershipPackageRepository packages;private final AuditRecorder audit;public DefaultMemberMembershipService(MemberMembershipRepository m,MembershipPackageRepository p,AuditRecorder a){memberships=m;packages=p;audit=a;}@Override @Transactional public MemberMembershipView grant(CurrentActor a,GrantMembershipCommand c){if(a==null||a.tenantId()==null||!a.roles().contains(RoleCode.GYM_ADMIN)||!a.hasPermission("membership:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!a.tenantId().equals(c.tenantId()))throw new BusinessException(ErrorCode.FORBIDDEN);MembershipPackage p=packages.findByTenantIdAndId(a.tenantId(),c.packageId()).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));MemberMembership m=memberships.save(MemberMembership.create(a.tenantId(),c.memberId(),c.packageId(),p.getEntitlementCount(),c.startsAt(),c.expiresAt()));audit.record(new AuditEvent("MEMBERSHIP_GRANTED","MEMBERSHIP",m.getId(),AuditResult.SUCCESS,"membership-service",Map.of()));return MemberMembershipView.from(m);}}
